+      box-shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
+      backdrop-filter: blur(20px);
+    }
+
+    .eyebrow {
+      margin: 0 0 10px;
+      color: #38bdf8;
+      font-size: 0.78rem;
+      font-weight: 700;
+      letter-spacing: 0.16em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(2rem, 5vw, 3rem);
+      line-height: 1;
+      letter-spacing: -0.05em;
+    }
+
+    .intro {
+      margin: 16px 0 30px;
+      color: #cbd5e1;
+      line-height: 1.65;
+    }
+
+    form {
+      display: grid;
+      gap: 20px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 8px;
+    }
+
+    label {
+      color: #e2e8f0;
+      font-size: 0.94rem;
+      font-weight: 700;
+    }
+
+    .required {
+      color: #67e8f9;
+    }
+
+    input {
+      width: 100%;
+      border: 1px solid rgba(148, 163, 184, 0.28);
+      border-radius: 16px;
+      outline: none;
+      padding: 15px 16px;
+      background: rgba(2, 6, 23, 0.66);
+      color: #f8fafc;
+      font: inherit;
+      transition: border-color 180ms ease, box-shadow 180ms ease, background 180ms ease;
+    }
+
+    input::placeholder {
+      color: #64748b;
+    }
+
+    input:focus {
+      border-color: #38bdf8;
+      background: rgba(2, 6, 23, 0.9);
+      box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.14);
+    }
+
+    .helper-text {
+      margin: 0;
+      color: #94a3b8;
+      font-size: 0.86rem;
+      line-height: 1.45;
+    }
+
+    button {
+      margin-top: 8px;
+      border: 0;
+      border-radius: 16px;
+      padding: 15px 18px;
+      background: linear-gradient(135deg, #38bdf8, #8b5cf6);
+      color: #020617;
+      cursor: pointer;
+      font: inherit;
+      font-weight: 800;
+      letter-spacing: -0.01em;
+      box-shadow: 0 16px 36px rgba(56, 189, 248, 0.22);
+      transition: transform 180ms ease, box-shadow 180ms ease, filter 180ms ease;
+    }
+
+    button:hover {
+      filter: brightness(1.08);
+      transform: translateY(-1px);
+      box-shadow: 0 20px 42px rgba(139, 92, 246, 0.28);
+    }
+
+    button:focus-visible {
+      outline: 3px solid rgba(103, 232, 249, 0.6);
+      outline-offset: 3px;
+    }
+
+    @media (max-width: 560px) {
+      .support-card {
+        padding: 28px 22px;
+        border-radius: 22px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main id="root"></main>
+
+  <script>
+    const h = (tag, props = {}, ...children) => {
+      const element = document.createElement(tag);
+
+      Object.entries(props).forEach(([key, value]) => {
+        if (key === "className") {
+          element.className = value;
+        } else if (key === "htmlFor") {
+          element.htmlFor = value;
+        } else if (value === true) {
+          element.setAttribute(key, "");
+        } else if (value !== false && value != null) {
+          element.setAttribute(key, value);
+        }
+      });
+
+      children.flat().forEach((child) => {
+        element.append(child instanceof Node ? child : document.createTextNode(child));
+      });
+
+      return element;
+    };
+
+    function FormField({ id, label, type = "text", required = false, placeholder, helperText, autocomplete }) {
+      return h(
+        "div",
+        { className: "form-field" },
+        h(
+          "label",
+          { htmlFor: id },
+          label,
+          required ? h("span", { className: "required", "aria-label": " required" }, " *") : ""
+        ),
+        h("input", {
+          id,
+          name: id,
+          type,
+          required,
+          placeholder,
+          autocomplete,
+          "aria-describedby": helperText ? `${id}-helper` : null
+        }),
+        helperText ? h("p", { className: "helper-text", id: `${id}-helper` }, helperText) : ""
+      );
+    }
+
+    function SupportContactForm() {
+      return h(
+        "section",
+        { className: "support-card", "aria-labelledby": "support-title" },
+        h("p", { className: "eyebrow" }, "Support"),
+        h("h1", { id: "support-title" }, "How can we help?"),
+        h("p", { className: "intro" }, "Send your details to our support team and we will get back to you as soon as possible."),
+        h(
+          "form",
+          { action: "#", method: "post", novalidate: true },
+          FormField({
+            id: "full-name",
+            label: "Full name",
+            required: true,
+            placeholder: "Alex Morgan",
+            autocomplete: "name"
+          }),
+          FormField({
+            id: "email-address",
+            label: "Email address",
+            type: "email",
+            required: true,
+            placeholder: "alex@example.com",
+            autocomplete: "email"
+          }),
+          FormField({
+            id: "phone-number",
+            label: "Phone number",
+            type: "tel",
+            placeholder: "+1 555 123 4567",
+            helperText: "Use international format when possible, for example +1 555 123 4567.",
+            autocomplete: "tel"
+          }),
+          h("button", { type: "submit" }, "Submit request")
+        )
+      );
+    }
+
+    document.getElementById("root").append(SupportContactForm());
+  </script>
+</body>
+</html>
*** End Patch
